  push ds                                      ; 07831  0x1E
  mov ds, [cs:0xc06]                           ; 07832  0x2E, 0x8E, 0x1E, 0x06, 0x0C
  mov bx, [cs:0x68]                            ; 07837  0x2E, 0x8B, 0x1E, 0x68, 0x00
