  db 0x33, 0xDB                                ; 0783F  xor bx, bx
  db 0x8A, 0xD8                                ; 07841  mov bl, al
  shl bx, 1                                    ; 07843  0xD1, 0xE3
  call word [cs:bx + 0xcac]                    ; 07845  0x2E, 0xFF, 0x97, 0xAC, 0x0C
  pop ds                                       ; 0784A  0x1F
  iret                                         ; 0784B  0xCF
